mCarnival_ExChange[3200697][1][5]["RandomItemChanceType"] = 2	tSumCarnival_ExChange[3200697][1][5]["ItemChance"] = 1500	tSumCarnival_ExChange[3200697][1][5]["Item_1"] = 5	tSumCarnival_ExChange[3200697][1][5]["GetItem"] = 3200705	tSumCarnival_ExChange[3200697][1][5]["GetNum"] = 1	tSumCarnival_ExChange[3200697][1][6] = {}	tSumCarnival_ExChange[3200697][1][6]["RandomItemChanceType"] = 2	tSumCarnival_ExChange[3200697][1][6]["ItemChance"] = 600	tSumCarnival_ExChange[3200697][1][6]["Item_1"] = 6	tSumCarnival_ExChange[3200697][1][6]["GetItem"] = 1088000	tSumCarnival_ExChange[3200697][1][6]["GetNum"] = 3	tSumCarnival_ExChange[3200697][1][7] = {}	tSumCarnival_ExChange[3200697][1][7]["RandomItemChanceType"] = 2	tSumCarnival_ExChange[3200697][1][7]["ItemChance"] = 400	tSumCarnival_ExChange[3200697][1][7]["Item_1"] = 7	tSumCarnival_ExChange[3200697][1][7]["GetItem"] = 723694	tSumCarnival_ExChange[3200697][1][7]["GetNum"] = 1	tSumCarnival_ExChange[3200697][1][8] = {}	tSumCarnival_ExChange[3200697][1][8]["RandomItemChanceType"] = 2	tSumCarnival_ExChange[3200697][1][8]["ItemChance"] = 100	tSumCarnival_ExChange[3200697][1][8]["Item_1"] = 8	tSumCarnival_ExChange[3200697][1][8]["GetItem"] = 3200703	tSumCarnival_ExChange[3200697][1][8]["GetNum"] = 1	------------------------------------------逻辑部分------------------------------------------ 物品使用function SumCarnival_JoyCoin(nItemId)	if Sys_ChkFullTime(tSumCarnival_Cont["BeforeActivityTime"]) then		return	end	if not Sys_ChkFullTime(tSumCarnival_Cont["ActivityTime"]) then		if Item_DelAllItemByType(nItemId) then			Sys_MsgBox(tSumCarnival_Text["Msg"]["OverTime"])			Sys_SaveActionFestivalLog(tSumCarnival_Log["OverTime"])			return		end	end	Sys_MsgBox(tSumCarnival_Text["Msg"]["PathFind"],"NpcPosition_PathFind</N>"..tostring(tSumCarnival_Cont["MainNpc"]))endfunction SumCarnival_Pack(nItemId)	RewardTemplate_UseItem(tSumCarnival_Pack[nItemId])	-- if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then		-- RewardTemplate_Reward(tSumCarnival_Pack[nItemId])		-- User_EffectAdd("self",tSumCarnival_Cont["Pack"])	-- endend--是否是限量奖励function SumCarnival_LimitChk(nAwardItemId)	for i,v in ipairs(tSumCarnival_Cont["LimitNum"]["Items"]) do		if nAwardItemId == v then			return true		end	end	return falseendfunction SumCarnival_GetReward(nItemId)	local nGlobalId = tSumCarnival_Cont["GlobalId"][nItemId]	local flat,tTable = Probabil_RandomAward(tSumCarnival_ExChange[nItemId],1)	local nAwardItemId = tTable[1]["tAward"][1]["GetItem"]	local sAttr = tTable[1]["tAward"][1]["Attr"] or ("0 "..tostring(tTable[1]["tAward"][1]["GetNum"]))		if SumCarnival_LimitChk(nAwardItemId) then		local nPos = tSumCarnival_Cont["LimitNum"][nItemId][nAwardItemId][1] 		local nLimitNum = tSumCarnival_Cont["LimitNum"][nItemId][nAwardItemId][2] 		local nReplace = tSumCarnival_Cont["LimitNum"][nItemId][nAwardItemId][3] 		local nNowNum = Get_SysDynaGlobalData(nGlobalId,nPos) or 0		if nNowNum >= nLimitNum then			nAwardItemId = nReplace			sAttr = "0 1"		else			nNowNum = nNowNum+1			Sys_SetSynaGlobalData(nGlobalId,nPos,nNowNum)		end	end		return nAwardItemId,sAttr,tTable[1]["tAward"][1]["GetNum"]end--大礼盒使用function SumCarnival_CarnivalPack(nItemId)	if not User_CheckLeftSpace(tSumCarnival_ExChange[nItemId]["Space"]) then		Sys_MsgBox(string.format(tSumCarnival_Text["Msg"]["NoSpace"],tSumCarnival_ExChange[nItemId]["Space"]))		return	end		local nAwardItemId,sAttr,nGetNum = SumCarnival_GetReward(nItemId)	local tRewardTemp = {}	tRewardTemp["RewardItem"] = {}				tRewardTemp["RewardItem"][1] = {}			tRewardTemp["RewardItem"][1]["Id"] = nAwardItemId	tRewardTemp["RewardItem"][1]["Attr"] = sAttr	tRewardTemp["Talk"] = string.format(tSumCarnival_Text["Msg"]["CarnivalPack"],nGetNum,Get_ItemtypeName(nAwardItemId))	tRewardTemp["Log"] = string.format(tSumCarnival_Log["CarnivalPack"],nItemId,nAwardItemId,nGetNum)	tRewardTemp["RewardEffect"] = {}	tRewardTemp["RewardEffect"]["Effect"] = tSumCarnival_Cont["Effect"]["Pack"]		local sEmLog = tSumCarnival_Log["Emoney"][nAwardItemId]	if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then		RewardTemplate_Reward(tRewardTemp)		Sys_SaveEmoneyBuy(sEmLog)	endend--外套包使用function SumCarnival_CoatSelect(nItemId)	local  sText = tSumCarnival_Text["Msg"]["CoatSelect"][nItemId]	Sys_DialogText(sText)	for i,v in ipairs(tSumCarnival_Pack[nItemId]["ItemId"]) do		local sName = Get_ItemtypeName(v)		local sOptionText = sName.."."		local sFunc = "</F>SumCarnival_CoatComfirm</N>"..nItemId.."</N>"..v		Sys_DialogOption(sOptionText,sFunc)	end	Sys_DialogEnd()end--2次确认function SumCarnival_CoatComfirm(nItemId,nCoat)	local sName = Get_ItemtypeName(nCoat)	local sText =string.format(tSumCarnival_Text["Msg"]["Comfirm"][nItemId],sName)	local sFunc1 = "</F>SumCarnival_CoatGet</N>"..nItemId.."</N>"..nCoat	local sFunc2 = "</F>SumCarnival_CoatSelect</N>"..nItemId	Sys_DialogText(sText)	Sys_DialogOption(tSumCarnival_Text["Msg"]["ComfirmOpt1"],sFunc1)	Sys_DialogOption(tSumCarnival_Text["Msg"]["ComfirmOpt2"],sFunc2)	Sys_DialogEnd()endfunction SumCarnival_CoatGet(nItemId,nCoat)	if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then		local sName = Get_ItemtypeName(nCoat)		local sText = string.format(tSumCarnival_Text["Msg"]["CoatGet"][nItemId],sName)		local sLog =  string.format(tSumCarnival_Log["Pack"],nItemId,nCoat)		Item_AddNewItem(nCoat,tSumCarnival_Pack[nItemId]["Attr"])		Sys_SaveActionFestivalLog(sLog)		Sys_MsgBox(sText)		User_EffectAdd("self",tSumCarnival_Cont["Effect"]["Pack"])			endend--查看兑换币投入情况。function SumCarnival_Rank(nNpcId)	local nEvent = tSumCarnival_Stc["Event"] 	local nType = tSumCarnival_Stc["Type"]["DailyRecord"]	local	nData = 0	local	nGlobalId = tSumCarnival_Cont["GlobalId"]["First"]	local	nPoint = Get_SysDynaGlobalData2(nGlobalId) or 0	local	sPlayerName = Get_SysDynaGlobalDataStr3(nGlobalId) or tSumCarnival_Text["Msg"]["NoRank"]	Task_StcReset(nEvent,nType)	nData = Get_UserStatisticValue(nEvent,nType)	tNpcGossip[11148]["Text152"] = string.format(tSumCarnival_Text[11148]["Text152"],sPlayerName)	tNpcGossip[11148]["Text153"] = string.format(tSumCarnival_Text[11148]["Text153"],nPoint)	tNpcGossip[11148]["Text154"] = string.format(tSumCarnival_Text[11148]["Text154"],nData)	LinkNpcGossipFunc_New(nNpcId,"1-5")end--打开活动页面。function SumCarnival_WebSite()	User_SendWebDialog(tSumCarnival_Cont["WebSite"])end--兑换纪念币function SumCarnival_ExChg(nNpcId,nExChgNum)	if not Sys_ChkFullTime(tSumCarnival_Cont["ActivityTime"]) then		Sys_MsgBox(tSumCarnival_Text["Msg"]["NoActivityTime"])		return	end	if not Item_ChkMulItem(tSumCarnival_Cont["ExItem"],tSumCarnival_Cont["ExItem"],nExChgNum) then		Sys_MsgBox(tSumCarnival_Text["Msg"]["NoExItem"])		return	end	if not User_CheckLeftSpace(1) then		Sys_MsgBox(tSumCarnival_Text["Msg"]["NoSpace"])		return	end		if Item_DelMulItem(tSumCarnival_Cont["ExItem"],tSumCarnival_Cont["ExItem"],nExChgNum) then		local tRewardTemp = {}		tRewardTemp["RewardItem"] = {}						tRewardTemp["RewardItem"][1] = {}						tRewardTemp["RewardItem"][1]["Id"] = tSumCarnival_Cont["ExChgItem"][nNpcId]		--物品Id		tRewardTemp["RewardItem"][1]["Attr"] = "0 1"		--物品属性.		tRewardTemp["Talk"] = tSumCarnival_Text[nNpcId]["ExChg"]		tRewardTemp["Log"] = string.format(tSumCarnival_Log["ActionLog"],nExChgNum,tSumCarnival_Cont["ExChgItem"][nNpcId],1)		tRewardTemp["RewardEffect"] = {}		tRewardTemp["RewardEffect"]["Effect"] = tSumCarnival_Cont["Effect"]["Npc"]				local nEvent = tSumCarnival_Stc["Event"] 		local nType = tSumCarnival_Stc["Type"]["DailyRecord"]		Task_StcReset(nEvent,nType)		Task_AddStatistic(nEvent,nType,nExChgNum,1)		SumCarnival_RankChg()		RewardTemplate_Reward(tRewardTemp)	end	end--排名变化function SumCarnival_RankChg()	local nEvent = tSumCarnival_Stc["Event"] 	local nType = tSumCarnival_Stc["Type"]["DailyRecord"]	local	nData = 0	local	nGlobalId = tSumCarnival_Cont["GlobalId"]["First"]	local	nPoint = Get_SysDynaGlobalData2(nGlobalId) or 0	Task_StcReset(nEvent,nType)	nData = Get_UserStatisticValue(nEvent,nType) or 0		if nData > nPoint then		Sys_SetSynaGlobalData2(nGlobalId,nData)		Sys_SetSynaGlobalData3(nGlobalId,Get_UserId())		Sys_SetSynaGlobalDataStr3(nGlobalId,Get_UserName())	endend--每天清零function SumCarnival_DayReset()	if not Sys_ChkFullTime(tSumCarnival_Cont["ActivityTime"]) then		return	end	if (Get_SysDynaGlobalData1(tSumCarnival_Cont["GlobalId"]["Reset"]) == 0) then		Sys_SetSynaGlobalData1(tSumCarnival_Cont["GlobalId"]["Reset"],1)			Sys_ResetAllSynaGlobalData(tSumCarnival_Cont["GlobalId"][3200696])		Sys_ResetAllSynaGlobalData(tSumCarnival_Cont["GlobalId"][3200697])		Sys_SetSynaGlobalData2(tSumCarnival_Cont["GlobalId"]["First"],0)		Sys_SetSynaGlobalData3(tSumCarnival_Cont["GlobalId"]["First"],0)		Sys_SetSynaGlobalDataStr3(tSumCarnival_Cont["GlobalId"]["First"],tSumCarnival_Text["Msg"]["NoRank"])	endendfunction SumCarnival_DayReset2()	if not Sys_ChkFullTime(tSumCarnival_Cont["ActivityTime"]) then		return	end	if (Get_SysDynaGlobalData1(tSumCarnival_Cont["GlobalId"]["Reset"]) > 0) then		Sys_SetSynaGlobalData1(tSumCarnival_Cont["GlobalId"]["Reset"],0)	endendfunction SumCarnival_FireWorks()	for i,v in ipairs(tSumCarnival_Cont["FireWorks"]) do		local nMapId = v[1]		local nPosX = v[2]		local nPosY = v[3]		Map_Effect(nMapId, nPosX, nPosY,tSumCarnival_Cont["Effect"]["Map"])	endend--------------------------------------------nPC-------------------------------------tNpcFace[4255] = 119tNpcGossip[11148] = tNpcGossip[11148] or DefaultNpc:new{}tNpcGossip[11148]["OptionHidden"] = 1tNpcGossip[11149] = tNpcGossip[11149] or DefaultNpc:new{}tNpcGossip[11149]["OptionHidden"] = 1tNpcGossip[11150] = tNpcGossip[11150] or DefaultNpc:new{}tNpcGossip[11150]["OptionHidden"] = 1--暑期狂欢大使 活动前tNpcGossip[11148]["Text1-1"] = {111,112,113,114}tNpcGossip[11148]["tOption1-1"] = {111}tNpcGossip[11148]["Text111"] = tSumCarnival_Text[1